71	// ParseReleaseInput reads a release plan document and validates its fields.
72	// Every string in the document — member names and values, in known fields
73	// and in unknown extra fields — must be legal text: invalid UTF-8 bytes and
74	// \uXXXX escapes naming an unpaired surrogate are rejected first, before any
75	// decoded string can be silently rewritten to "�" and compared. Every JSON
76	// object in the document — including unknown fields and their nested
77	// objects — must then have distinct member names; a name appearing twice
78	// (even with the same value, or via equivalent Unicode escapes) is rejected
79	// before any business validation runs.
80	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
81		if err := checkStrictText(data); err != nil {
82			return ReleasePlanInput{}, err
83		}
84		if err := checkDuplicateMembers(data); err != nil {
85			return ReleasePlanInput{}, err
86		}
87		dec := json.NewDecoder(bytes.NewReader(data))
88		dec.UseNumber()
89		var doc map[string]any
90		if err := dec.Decode(&doc); err != nil {
91			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
92		}
93		if dec.More() {
94			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
95		}
96		return buildReleaseInput(doc)
97	}
98	
99	// duplicateMemberError reports a JSON object whose member name appears more
100	// than once. Path is a JSONPath-style location that points at the object
101	// owning the duplicate (the duplicate member name itself is reported
102	// separately in field): "$" for the document root, "$.clusters[1]" for a
103	// cluster, "$.clusters[0].tags" for a tag object,
104	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
105	// objects nested inside unknown fields. A member name that is not a plain
106	// identifier is wrapped in brackets around a JSON string, so that characters
107	// in the name can never be read as hierarchy or an array index: a top-level
108	// member "meta.info" is at $["meta.info"] (distinct from the nested object
109	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
110	// that are empty or contain quotes, backslashes or control characters are
111	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
112	type duplicateMemberError struct {
113		field string
114		path  string
115	}
116	
117	func (e *duplicateMemberError) Error() string {
118		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
119	}
120	
121	// checkDuplicateMembers walks every JSON object in data and rejects objects
122	// with duplicate member names. Names are compared after JSON decoding, so
123	// "env" and "env" are the same name while "env" and "ENV", or
124	// " env" and "env", are different. The first duplicate encountered in file
125	// order is reported: the walk is depth-first in document order, so the
126	// second occurrence that appears earliest wins, regardless of value type.
127	//
128	// The check is a policy over the shared structural walk (jsonwalk.go): the
129	// walker recognizes the nesting, decodes the member names and tracks each
130	// object's location; this check only keeps the seen-name set of each object.
131	// A document the walk cannot fully vouch for — an unrecognized structure,
132	// trailing content, or a loosely scanned number only the decoder judges —
133	// is handed to the encoding/json walk, which reports the established format
134	// error (and any duplicate preceding the malformation) with the existing
135	// wording.
136	func checkDuplicateMembers(data []byte) error {
137		dup, recognized := scanDuplicateMembers(data)
138		// json.Valid confirms the whole document — including the numbers the
139		// walk skipped loosely and any trailing content — is one well-formed
140		// JSON value, so a completed walk's verdict can be trusted directly.
141		// Legal numbers beyond float64 range (e.g. 1e400) are valid JSON and
142		// pass; whether a number is acceptable for a given field is decided
143		// later by business validation.
144		if recognized && json.Valid(data) {
145			return dup
146		}
147		return checkJSONFormatAndDuplicates(data)
148	}
149	
150	// scanDuplicateMembers runs the duplicate-member policy over the shared
151	// structural walk. It reports the first duplicate in file order — the walk
152	// is depth-first in document order, so the second occurrence that appears
153	// earliest wins — and whether the walk recognized the document's structure
154	// (no errUndecided and no text problem, both of which leave the verdict to
155	// the decoder walk). recognized does not by itself mean the document is
156	// well-formed JSON: the caller confirms that with json.Valid.
157	func scanDuplicateMembers(data []byte) (dup error, recognized bool) {
158		// Each object's location in the document is unique, so the seen-name
159		// sets are keyed by the owning object's path; the walk needs no
160		// enter/exit events for them.
161		seen := make(map[string]map[string]struct{})
162		w := &jsonWalker{data: data, onMember: func(ownerPath, name string) error {
163			set := seen[ownerPath]
164			if set == nil {
165				set = make(map[string]struct{})
166				seen[ownerPath] = set
167			}
168			if _, ok := set[name]; ok {
169				dup = &duplicateMemberError{field: name, path: ownerPath}
170				return dup
171			}
172			set[name] = struct{}{}
173			return nil
174		}}
175		if err := w.value("$"); err != nil && dup == nil {
176			return nil, false
177		}
178		return dup, true
179	}
180	
181	// checkJSONFormatAndDuplicates is the encoding/json walk that documents the
182	// raw structural walk cannot recognize are handed to. It reports the JSON
183	// format error with the established wording — and a duplicate member when
184	// its second occurrence precedes the malformation — exactly as the duplicate
185	// check always has for such documents.
186	func checkJSONFormatAndDuplicates(data []byte) error {
187		dec := json.NewDecoder(bytes.NewReader(data))
188		// Numbers are only walked past, never interpreted: UseNumber keeps legal
189		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
190		// unmarshal-overflow error here. Whether a number is acceptable for a given
191		// field is decided later by business validation.
192		dec.UseNumber()
193		if err := walkJSONValue(dec, "$"); err != nil {
194			return err
195		}
196		if _, err := dec.Token(); err != io.EOF {
197			if err == nil {
198				return errors.New("JSON 格式错误: 文档包含多余内容")
199			}
200			return fmt.Errorf("JSON 格式错误: %w", err)
201		}
202		return nil
203	}
204	
205	// walkJSONValue reads one complete JSON value whose first token has not been
206	// consumed yet. Together with walkJSONObject and walkJSONArray it is the
207	// decoding half of checkJSONFormatAndDuplicates: it only runs for documents
208	// the shared structural walk could not recognize, to report the format error
209	// (or an earlier duplicate) with the established wording.
210	func walkJSONValue(dec *json.Decoder, path string) error {
211		tok, err := dec.Token()
212		if err != nil {
213			if err == io.EOF {
214				return errors.New("JSON 格式错误: 文档为空")
215			}
216			return fmt.Errorf("JSON 格式错误: %w", err)
217		}
218		return walkJSONValueToken(dec, path, tok)
219	}
220	
221	// walkJSONValueToken reads the remainder of a value given its first token.
222	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
223		if d, ok := tok.(json.Delim); ok {
224			switch d {
225			case '{':
226				return walkJSONObject(dec, path)
227			case '[':
228				return walkJSONArray(dec, path)
229			default:
230				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
231			}
232		}
233		return nil // scalar value (string, number, bool, null)
234	}
235	
236	func walkJSONObject(dec *json.Decoder, path string) error {
237		seen := make(map[string]struct{})
238		for {
239			tok, err := dec.Token()
240			if err != nil {
241				if err == io.EOF {
242					return errors.New("JSON 格式错误: 对象未闭合")
243				}
244				return fmt.Errorf("JSON 格式错误: %w", err)
245			}
246			if d, ok := tok.(json.Delim); ok {
247				if d == '}' {
248					return nil
249				}
250				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
251			}
252			key, ok := tok.(string)
253			if !ok {
254				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
255			}
256			if _, dup := seen[key]; dup {
257				return &duplicateMemberError{field: key, path: path}
258			}
259			seen[key] = struct{}{}
260			vtok, err := dec.Token()
261			if err != nil {
262				if err == io.EOF {
263					return errors.New("JSON 格式错误: 缺少成员值")
264				}
265				return fmt.Errorf("JSON 格式错误: %w", err)
266			}
267			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok); err != nil {
268				return err
269			}
270		}
271	}
272	
273	func walkJSONArray(dec *json.Decoder, path string) error {
274		for i := 0; ; i++ {
275			tok, err := dec.Token()
276			if err != nil {
277				if err == io.EOF {
278					return errors.New("JSON 格式错误: 数组未闭合")
279				}
280				return fmt.Errorf("JSON 格式错误: %w", err)
281			}
282			if d, ok := tok.(json.Delim); ok && d == ']' {
283				return nil
284			}
285			if err := walkJSONValueToken(dec, joinIndexPath(path, i), tok); err != nil {
286				return err
287			}
288		}
289	}
