	switch c := w.data[w.pos]; {
	case c == '{':
		return w.object(path)
	case c == '[':
		return w.array(path)
	case c == '"':
		_, err := w.jsonString(path, false)
		return err
	case c == 't':
		return w.literal("true")
	case c == 'f':
		return w.literal("false")
	case c == 'n':
		return w.literal("null")
	case c == '-' || ('0' <= c && c <= '9'):
