package main

import (
	"fmt"
	"os"
	"runtime"
	"strings"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

const prefix = `{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[],"x":`

func nestedObjs(n int) []byte {
	var b strings.Builder
	b.WriteString(prefix)
	b.WriteString(strings.Repeat(`{"a":`, n))
	b.WriteString(`1`)
	b.WriteString(strings.Repeat(`}`, n))
	b.WriteString(`}`)
	return []byte(b.String())
}

func main() {
	// boundary: root level 1 + n extra object levels
	for _, n := range []int{9998, 9999, 10000, 10001, 10002} {
		_, err := darksafe.ParseReleaseInput(nestedObjs(n))
		fmt.Fprintf(os.Stderr, "objects extra=%d total=%d: %v\n", n, n+1, err)
	}
	// arrays
	for _, total := range []int{9999, 10000, 10001, 10002} {
		var b strings.Builder
		b.WriteString(prefix)
		b.WriteString(strings.Repeat(`[`, total-1))
		b.WriteString(`1`)
		b.WriteString(strings.Repeat(`]`, total-1))
		b.WriteString(`}`)
		_, err := darksafe.ParseReleaseInput([]byte(b.String()))
		fmt.Fprintf(os.Stderr, "arrays total=%d: %v\n", total, err)
	}
	// mixed alternating { [
	for _, total := range []int{10000, 10001} {
		var b strings.Builder
		b.WriteString(prefix)
		for i := 0; i < total-1; i++ {
			if i%2 == 0 {
				b.WriteString(`[`)
			} else {
				b.WriteString(`{"k":`)
			}
		}
		b.WriteString(`1`)
		for i := total - 2; i >= 0; i-- {
			if i%2 == 0 {
				b.WriteString(`]`)
			} else {
				b.WriteString(`}`)
			}
		}
		b.WriteString(`}`)
		_, err := darksafe.ParseReleaseInput([]byte(b.String()))
		fmt.Fprintf(os.Stderr, "mixed total=%d: %v\n", total, err)
	}
	// unterminated: no closing brackets at all
	for _, total := range []int{10000, 10001, 10002, 100000} {
		doc := prefix + strings.Repeat(`[`, total-1)
		_, err := darksafe.ParseReleaseInput([]byte(doc))
		fmt.Fprintf(os.Stderr, "unterminated arrays total=%d: %v\n", total, err)
	}
	// braces inside strings must not count
	{
		doc := prefix + strings.Repeat(`{"s":"{{{[[[}}}"],"x":`, 100) + `1` + strings.Repeat(`}`, 100) + `}`
		_, err := darksafe.ParseReleaseInput([]byte(doc))
		fmt.Fprintf(os.Stderr, "braces-in-strings depth=101: %v\n", err)
	}
	// huge depth: message length constant, process survives
	{
		var m0, m1 runtime.MemStats
		runtime.GC()
		runtime.ReadMemStats(&m0)
		doc := prefix + strings.Repeat(`[`, 500000)
		_, err := darksafe.ParseReleaseInput([]byte(doc))
		runtime.ReadMemStats(&m1)
		fmt.Fprintf(os.Stderr, "500k unterminated: %v (msg len %d, heap +%dMB)\n", err, len(err.Error()), (m1.HeapAlloc-m0.HeapAlloc)/1024/1024)
	}
	// caller continues after a depth failure
	{
		in, err := darksafe.ParseReleaseInput(nestedObjs(10001))
		fmt.Fprintf(os.Stderr, "deep fail zero input: in=%+v err-non-nil=%v\n", in, err != nil)
		good, err2 := darksafe.ParseReleaseInput([]byte(`{"app":"a","revision":"r","image":"i","batchSize":1,"clusters":[{"id":"c1"}]}`))
		fmt.Fprintf(os.Stderr, "after failure, good config: clusters=%d err=%v\n", len(good.Clusters), err2)
	}
}
EOF
