// TestParse_DepthCheckDoesNotChangeOtherPriorities checks the interaction
// with the other structural verdicts: a duplicate before the too-deep
// value in file order is reported first (the walk is depth-first in
// document order); a too-deep opener reached first aborts before a later
// duplicate is seen; a document at exactly the limit with a duplicate
// still gets its duplicate error; and a shallow malformed document keeps
// its ordinary format error.
func TestParse_DepthCheckDoesNotChangeOtherPriorities(t *testing.T) {
	deep := deepValue(`[`, `]`, maxJSONNestingDepth)

	// Duplicate member appears before the deep value: duplicate wins.
	dupFirst := `{"app":"a","app":"b","revision":"r","image":"i","batchSize":1,` +
		`"clusters":[],"x":` + deep + `}`
	if _, err := ParseReleaseInput([]byte(dupFirst)); err == nil ||
		!strings.Contains(err.Error(), "重复成员") || !strings.Contains(err.Error(), `"app"`) {
		t.Fatalf("earlier duplicate must win, got %v", err)
	}

	// Deep value appears before the duplicate later in the same object:
	// the depth limit aborts the walk first.
	deepFirst := `{"app":"a","revision":"r","image":"i","batchSize":1,` +
		`"clusters":[],"x":` + deep + `,"app":"b"}`
	if _, err := ParseReleaseInput([]byte(deepFirst)); err == nil ||
		err.Error() != wantDepthMsg() {
		t.Fatalf("depth reached first must win, got %v", err)
	}

	// Exactly 10000 levels plus a duplicate: the duplicate verdict stands.
	atLimitWithDup := `{"app":"a","revision":"r","image":"i","batchSize":1,` +
		`"clusters":[],"x":` + deepValue(`[`, `]`, maxJSONNestingDepth-1) +
		`,"revision":"r2"}`
	if _, err := ParseReleaseInput([]byte(atLimitWithDup)); err == nil ||
		!strings.Contains(err.Error(), "重复成员") {
		t.Fatalf("at-limit document must still be checked for duplicates, got %v", err)
	}

	// A shallow malformed document is unaffected by the depth rule.
	if _, err := ParseReleaseInput([]byte(`{not json`)); err == nil ||
		!strings.HasPrefix(err.Error(), "JSON 格式错误") {
		t.Fatalf("shallow malformed documents keep their format error, got %v", err)
	}
}

