// maxJSONNestingDepth is the only nesting depth a release configuration
// document may have. The outermost value counts as level 1 and every
// entered object or array adds one, whether the two kinds are mixed or
// not; siblings at the same level do not add up. Braces that appear inside
// a string literal — written directly or as an escape such as { —
// are text, not structure, and are never counted. The limit matches the
// one encoding/json enforces, so a document at exactly 10000 levels still
// parses while the 10001st opener is refused everywhere.
const maxJSONNestingDepth = 10000

